@startuml

class Student {
  + studentID : int
  + birthDate : date
  + birthCity : string
  + birthRegion : string
}

class Professor {
  + name : string
  + birthDate : date
  + birthCity : string
}

class Faculty {
  + name : string
  + type : string
}

class Course {
  + code : string
  + lectureHours : int
}

class Exam {
  + grade : float
}

class Enrollment {
  + enrollmentYear : int
}

Professor "1" -- "0..*" Course : teaches
Faculty "1" -- "0..*" Student : enrolls
Student "1" -- "0..*" Enrollment : has
Enrollment "0..*" -- "1" Faculty : in
Student "1" -- "0..*" Exam : passes
Exam "0..*" -- "1" Course : for

@enduml

